// frontier.mjs — derive the "ready to start" work items from a view (per D1
// Epic 2, A2 FIFO). PURE: no fs import, no side effects — this module only
// reads the `view` object it is handed (built by replay.mjs's `foldEvents`
// / `rebuildView`, or a literal view in tests) and returns a derived array.
// It never mutates `view` and never writes an event (the one exception is a
// diagnostic `console.warn` via domain-registry.mjs on a genuinely unrecognized
// `item.domain` value — never a throw, see base-workflow-model D2/D3).
import { getDomain, stepForPhase } from './domain-registry.mjs';
//
// Ready = status 'todo' AND every dep's status is RESOLVED (per D5: 'done'
// means "accepted into the main tree" — a dep sitting at 'awaiting-approval',
// 'doing', or 'blocked' does NOT unblock its dependents; per
// wontfix-terminal-status-filter-consistency D1, a dep at 'wontfix' DOES
// unblock its dependents — abandoned, nothing further will ever land for
// it, so waiting on it forever would be a silent permanent deadlock) AND
// stage at the
// item's own domain's Execute-mapped stage ('executing' for the 'coding'
// domain — per stage-clarify D1: an item still at stage `clarify` is not
// yet "ready to start" no matter its status — `fgos ready` would otherwise
// lie about items that have not passed context-discovery; domain-aware per
// base-workflow-model D2/D3, domain-registry.mjs) AND no open descendant (per
// stage-decompose D4/D5: an item that was decomposed stays
// anchored — excluded from the frontier — for as long as any item reachable
// through the `parent` chain below it is not yet 'done'; this is a lineage
// filter DERIVED from `parent`, never `deps` — a child is never written into
// its parent's `deps`). `stage` is read lazily — `item.stage ?? <the item's
// domain's Execute stage>` (D8; domain-aware per base-workflow-model D2/D3)
// — so an item predating this field behaves exactly as before, and an
// item with no `parent` anywhere in the view is likewise never blocked by
// this filter (backward-compat). Frontier is a derived read (R5 — "derive,
// no danh sách tay"), never a stored list.
//
// FIFO order (per A2, cold-pickup reliance — deliberately spelled out, not
// left implicit):
//   - `view.work` is a plain object built by replay.mjs's `foldEvents`,
//     which assigns `view.work[item.id] = ...` in the order `work.add`
//     events are folded — i.e. declaration order.
//   - `work.move` (see replay.mjs) only ever does `item.status = to` on the
//     existing entry; it never deletes/re-inserts the key, so a status
//     change never moves an id's position in iteration order.
//   - Every work id is validated kebab-case, starting with a letter
//     (work.mjs ID_PATTERN) — never an all-digit / numeric-looking string —
//     so none of these keys fall into the "integer index" bucket the JS
//     spec special-cases (those would iterate in ascending numeric order
//     ahead of insertion-order string keys, which would silently break
//     FIFO). `Object.keys(view.work)` therefore always iterates in
//     declaration (insertion) order, which is what `frontier` relies on for
//     FIFO — it never sorts by id.
// TIE-BREAK CONTRACT (work-graph-intelligence S4, bumped to v2 by
// str7-str8-priority-intent D2). `frontier(view)` is the single, versioned
// surface that decides claim order: the order it returns IS the order the
// runner claims and dispatches in (consumers `readyWork` in store.mjs and
// `steerFrontier` in the runner take this order as given, never re-sorting).
// `FRONTIER_ORDER_VERSION` names that order so a change to it is deliberate
// and visible, never an accidental reorder of a cold-pickup-critical
// invariant.
//
//   - v1 (superseded): the SOLE ordering key was FIFO by `work.add`
//     declaration order — exactly the insertion-order iteration argued for
//     in the header comment above. No priority, no intent, no re-sort.
//   - v2 (current, per D1/D2/D6): three ordering keys, applied in order —
//     (1) `priority` ASCENDING, absent-last (an item with no `priority`
//     sorts strictly after every item that has one, regardless of the
//     latter's magnitude); (2) among ties on (1), `intent` DESCENDING, same
//     absent-last bucketing; (3) among ties on (1) and (2), declaration
//     order — the v1 tie-break, preserved for free by
//     `Array.prototype.sort`'s spec-guaranteed stability on Node >=18 (this
//     repo's engines requirement): a comparator that returns 0 once both
//     keys tie never reorders those items relative to each other, so no
//     third key is hand-written here.
//
// A view where no item has `priority` or `intent` set produces the exact v1
// order (every comparison short-circuits both absent-last branches to a tie,
// i.e. "keep declaration order") — v2 is a strict backward-compatible
// superset of v1, not a behavior change for existing data.
export const FRONTIER_ORDER_VERSION = 2;

// `phase` (generalized for fgos-coding-driving's own loop): which Workflow phase
// counts as "ready to start" — defaults to `'execute'` (every unparameterized
// caller gets that behavior). A driver loop wanting the frontier for an earlier
// phase (e.g. `'clarify'`/`'plan'`, mirroring discover-loop/planning-loop's own
// pools) passes it explicitly; `isDepsAndLineageReady` below already covers the
// step-independent half of readiness this parameterizes the step half of.
export function frontier(view, { phase = 'execute' } = {}) {
  const work = view?.work ?? {};
  const childrenByParent = indexChildrenByParent(work);
  const ready = [];
  for (const id of Object.keys(work)) {
    const item = work[id];
    if (!isTodoStatus(item)) continue;
    // Domain-aware: an unrecognized item.domain never throws here
    // (domain-registry.mjs's fail-safe) — it folds to 'coding' with a
    // diagnostic warning, so a corrupt/rolled-back domain value can never
    // wedge the frontier derive itself.
    const domain = getDomain(item.domain);
    const phaseStep = stepForPhase(domain, phase, item.kind);
    // A domain that never declares a step for `phase` at all (e.g. `synthetic`
    // has no clarify/plan, only execute -> `assembling`) has NO item ready for
    // it, full stop -- guarded separately from the `??` fallback below, which
    // would otherwise wrongly admit an item with no `workflowStep` at all
    // (undefined ?? undefined === undefined, a false tie).
    if (phaseStep === undefined) continue;
    if ((item.workflowStep ?? stepForPhase(domain, 'execute', item.kind)) !== phaseStep) continue;
    if (hasOpenDescendant(id, work, childrenByParent)) continue;
    const depsReady = item.deps.every((dep) => isResolvedStatus(work[dep]));
    if (depsReady) ready.push(item);
  }
  ready.sort(compareReadyOrder);
  return ready;
}

// Union of `frontier(view, {phase})` across multiple phases (tsk-4so D1,
// docs/history/execution-fanout/CONTEXT-tsk-4so.md): a footprint-overlap
// advisory that only ever looks at one step is structurally blind to two
// items at DIFFERENT steps sharing a footprint — the real gap this exists
// to close (tsk-1ug at `decompose` vs tsk-4fg/tsk-59x at `executing`, all
// three declaring the same file, `fgos conflicts` reporting zero pairs).
// Dedupes by id: an item with no `workflowStep` field matches EVERY phase's
// execute-step fallback (`item.workflowStep ?? <execute step>` above), so without
// dedup it would appear once per step in `steps` instead of once overall.
// Re-sorts the deduped set once with `compareReadyOrder` — concatenating
// three already-sorted arrays would NOT preserve `FRONTIER_ORDER_VERSION`'s
// priority/intent ordering across the combined set. PURE: same read-only
// contract as `frontier`.
export function frontierAcrossSteps(view, phases = ['clarify', 'plan', 'execute']) {
  const seen = new Map();
  for (const phase of phases) {
    for (const item of frontier(view, { phase })) {
      if (!seen.has(item.id)) seen.set(item.id, item);
    }
  }
  return [...seen.values()].sort(compareReadyOrder);
}

// True when `item` is at the front-segment "not yet started" bucket (per
// decision record 0027, D2/D3: statusCategory 'todo') — used by the `ready`
// filter above so a domain that relabels its "not started" status away from
// the literal string 'todo' is still picked up correctly (frontier.mjs:92
// row of 0027's own audit table). Reads `item.statusCategory` when present;
// falls back to the literal `item.status === 'todo'` comparison when it is
// NOT present (an item written before tsk-38t-2 stamped this field at all,
// or an item whose domain declares no `statusLabels` at all, e.g.
// `synthetic`/`triage` today) — this is a fallback to the pre-existing
// field, never a derive-on-read of the category table itself (which
// platform-foundations.md's L3 forbids, see STATUS_CATEGORIES's own doc
// comment in work.mjs), so it stays safe under replay-from-zero.
function isTodoStatus(item) {
  if (item.statusCategory !== undefined) return item.statusCategory === 'todo';
  return item.status === 'todo';
}

// Stage-independent readiness (choke-point-take-vs-pick-claim-eligibility):
// the same deps-done + no-open-descendant clauses `frontier` enforces,
// minus its stage clause — for a caller that intentionally wants to claim
// an item still at `clarify`/`decompose` (status and stage are independent
// axes, status-fsm.mjs; the same stance `pick`'s explicit-`--id` branch already
// takes) while still refusing a genuinely-blocked item (unmet dep, or
// anchored by an open decomposed child) — those two reasons stay real
// "not dispatchable" regardless of stage.
export function isDepsAndLineageReady(view, id) {
  const work = view?.work ?? {};
  const item = work[id];
  if (!item) return false;
  const childrenByParent = indexChildrenByParent(work);
  if (hasOpenDescendant(id, work, childrenByParent)) return false;
  return item.deps.every((dep) => isResolvedStatus(work[dep]));
}

// v2 comparator (D2/D6): priority ASC absent-last, then intent DESC
// absent-last, then declaration order — the last key falls out of
// Array.prototype.sort's guaranteed stability (see header comment above),
// so returning 0 on a full tie is the entire tie-break, not an omission.
function compareReadyOrder(a, b) {
  if (a.priority !== b.priority) {
    if (a.priority === undefined) return 1;
    if (b.priority === undefined) return -1;
    return a.priority - b.priority;
  }
  if (a.intent !== b.intent) {
    if (a.intent === undefined) return 1;
    if (b.intent === undefined) return -1;
    return b.intent - a.intent;
  }
  return 0;
}

// Reverse index of `parent` -> direct children ids. Items with no `parent`
// field never contribute an entry, so a view with no lineage at all yields
// an empty index and `hasOpenDescendant` below short-circuits to `false` for
// every id — the exact no-op this filter must be on a parent-less log.
export function indexChildrenByParent(work) {
  const index = {};
  for (const id of Object.keys(work)) {
    const parent = work[id].parent;
    if (!parent) continue;
    if (!index[parent]) index[parent] = [];
    index[parent].push(id);
  }
  return index;
}

// An item is RESOLVED when nothing further will happen to it that could
// still change the CODE/graph state a dependent or lineage check cares
// about. Per decision record 0027 (D1/D2, `docs/decisions/0027-domain-so-
// huu-status-doan-truoc-delivered-supersede-base-workflow-model-d1-d3.md`)
// this is now a HYBRID read, not a flat literal Set, because the 10
// statuses split into two groups with different rules (0027's own audit,
// §"Hệ quả 1 chi tiết", `docs/history/phase-2-status-category-schema/
// DISCUSSION.md` §6):
//   - the FOUR tail-segment statuses (`delivered`/`retrospective`/
//     `cleanup`/`done`) never get relabeled by any domain (D1) — literal
//     status is sufficient for them forever, checked first below;
//   - `wontfix` is a front-segment, domain-OWNED label that always maps to
//     `statusCategory: 'canceled'` (D2) — a domain that relabels it (e.g.
//     `declined`) must still be recognized as resolved, which a literal
//     `'wontfix'` string match could never do. Reading `item.statusCategory
//     === 'canceled'` instead is the whole point of this migration
//     (tsk-38t-4): every domain-agnostic consumer that used to `.has()` a
//     flat Set now calls `isResolvedStatus(item)` (the WHOLE item, not just
//     a status string — reading category needs the item) instead.
// `item.statusCategory` is frozen at write time only (store.mjs's
// addWork/moveWork) and NEVER derived on read (platform-foundations.md's L3
// — see STATUS_CATEGORIES's own doc comment, work.mjs) — an item written
// before tsk-38t-2 landed this field, or whose domain declares no
// `statusLabels` at all (`synthetic`/`triage` today), carries no
// `statusCategory`. For those, this falls back to the literal `'wontfix'`
// string — the ONLY front-segment status this set has ever recognized —
// so pre-migration data keeps replaying exactly as before (never a
// derive-on-read of the category table itself, only a fallback to the
// pre-existing `status` field, the same lazy-default shape every other
// optional-additive field in this codebase already uses).
//
// `fgos rollup`'s progress-reporting count is a SEPARATE mechanism and
// intentionally does NOT share this function — it still counts strict
// `done` only. Exported so every other consumer that needs "is this item
// resolved enough to stop counting it as open" (deps-readiness in this
// module's own `depsReady`/`isDepsAndLineageReady`, plus claim-port.mjs/
// impact.mjs/graph-metrics.mjs/entropy.mjs/graph-harness.mjs/
// drift-status.mjs — see wontfix-terminal-status-filter-consistency D1/D2/D3
// and 0027's own audit §2) shares this one function instead of separate
// ad-hoc re-declarations.
const TAIL_RESOLVED_STATUSES = new Set(['delivered', 'retrospective', 'cleanup', 'done']);
const LEGACY_CANCELED_STATUS = 'wontfix';

/** The canceled-only half of `isResolvedStatus` below, extracted (tsk-4bh)
 * for a caller that needs to tell "abandoned, never had content" apart from
 * "successfully resolved" — `isResolvedStatus` itself treats both as
 * equally fine to stop waiting on (deps-readiness, frontier lineage), but
 * `cleanup-harness.mjs`'s own merge-still-resolves ancestry check needs the
 * opposite split: skip a canceled/wontfix child entirely (it never had
 * content to merge, so there is nothing to check), while STILL verifying a
 * `done`/`delivered` child's recorded sha really is an ancestor (that
 * verification is the whole point of the check — `isResolvedStatus` alone
 * would wrongly skip it too). Never returns true for a tail-resolved status
 * (`done`/`delivered`/`retrospective`/`cleanup`) — those are the opposite
 * case this function exists to distinguish. */
export function isCanceledStatus(item) {
  if (!item) return false;
  if (TAIL_RESOLVED_STATUSES.has(item.status)) return false;
  if (item.statusCategory !== undefined) return item.statusCategory === 'canceled';
  return item.status === LEGACY_CANCELED_STATUS;
}

export function isResolvedStatus(item) {
  if (!item) return false;
  if (TAIL_RESOLVED_STATUSES.has(item.status)) return true;
  return isCanceledStatus(item);
}

/**
 * Resolve the root of the lineage tree `id` belongs to: walk `view.work[id].parent`
 * upward until reaching an item with no `parent` (or whose `parent` does not
 * resolve to a known item), and return THAT item's id. An item with no
 * `parent` is its own root and resolves to itself.
 *
 * Defensive backstop, mirroring `hasOpenDescendant` below: a `seen` set
 * guards against a cyclic or malformed parent chain turning this into an
 * infinite walk. Should not occur on real decompose-produced data — if a
 * cycle is detected, the walk stops and returns the current id rather than
 * looping forever.
 *
 * Lives here rather than in `runner/root-affinity.mjs` (its original home,
 * tsk-49i D1): it is a pure read over the same `view.work` parent chain the
 * rest of this module walks, and `state/` modules needing it had to import
 * across into `runner/` to get it — one of the import edges that made the
 * two folders mutually dependent.
 *
 * @param {{work: Record<string, {parent?: string|null}>}} view
 * @param {string} id
 * @returns {string}
 */
export function resolveRoot(view, id) {
  const work = view?.work ?? {};
  const seen = new Set();
  let current = id;
  while (true) {
    if (seen.has(current)) return current;
    seen.add(current);
    const item = work[current];
    const parent = item?.parent;
    if (!parent || !work[parent]) return current;
    current = parent;
  }
}

// True when `id` has any descendant (direct child, or a descendant reachable
// through further `parent` chains below a child) whose status is not yet
// RESOLVED. `seen` guards against a malformed/cyclic parent chain turning
// this into an infinite walk — it never occurs on data produced by the
// decompose engine, only a defensive backstop.
// See `loop.mjs`'s `hasStillNeededDescendant` for a deliberately BROADER
// 'still needed' variant used by `startupReap`'s orphan-branch pruning — the
// two intentionally answer different questions, do not consolidate.

export function hasOpenDescendant(id, work, childrenByParent, seen = new Set()) {
  const children = childrenByParent[id];
  if (!children) return false;
  for (const childId of children) {
    if (seen.has(childId)) continue;
    seen.add(childId);
    const child = work[childId];
    if (!child) continue;
    if (!isResolvedStatus(child)) return true;
    if (hasOpenDescendant(childId, work, childrenByParent, seen)) return true;
  }
  return false;
}

// graph-harness.mjs — merge-order ranking (tsk-4j9-2, docs/history/
// merge-standardization/). PURE: takes a work-state view (as returned by
// store.mjs's listWork/rebuildView) and returns which `proposed` items are
// actually ready to merge right now, in the order they should merge, plus
// which ones are waiting or conflicting. No fs, no Date.now(), no event
// append, no mutation — same read-only discipline as impact.mjs/
// graph-metrics.mjs.
//
// Composes three signals, each reused rather than reimplemented (CONTEXT.md
// D1/D3/D4-revised):
//   - dependency-wait gate: a `proposed` item whose own `deps` are not ALL
//     RESOLVED (frontier.mjs — delivered/retrospective/cleanup/done/wontfix)
//     yet waits — genuinely new, `approve` has no such check today.
//   - conflict detection: `footprintOverlapAmong` (extracted out of
//     `footprintOverlap`, D4-revised) over the dep-clear candidate set,
//     instead of `footprintOverlap`'s own frontier-only candidate set.
//   - impact ordering: `rankImpact`'s existing blocking-fan-out + goalTier
//     ordering (D3), filtered down to the conflict-free candidates rather
//     than re-implemented.
import { rankImpact } from './impact.mjs';
import { footprintOverlapAmong } from './graph-metrics.mjs';
import { isResolvedStatus, resolveRoot } from './frontier.mjs';
import { effectiveStep, getDomain } from './domain-registry.mjs';

/**
 * Rank `proposed` items by merge-readiness.
 *
 * `opts.drift` (tsk-2u0, docs/history/tsk-3bn-merge-conductor-harness-v2/):
 * an OPTIONAL pre-computed `driftStatus()` result (`{[rootId]: {needsSync,
 * ...}}`). This function stays PURE — it never calls `driftStatus` itself
 * (that module shells real git subprocesses, a different purity class,
 * per its own header comment) — a caller that wants `blockedOnSync`
 * populated computes drift separately and passes the result in. Omitting
 * `opts.drift` (every existing caller today) leaves `blockedOnSync` always
 * empty — a pure additive opt-in, zero behavior change for callers that
 * don't know about it yet.
 *
 * Returns `{ ready, waiting, conflicts, mergeSets, blockedOnSync,
 * mergeTier, supersededOut }`:
 *   - `ready` — ids of `proposed` items whose `deps`/`mergeAfter` are all
 *     RESOLVED, whose resolved root has no unresolved sync drift, and
 *     which are not part of any footprint conflict, ordered by
 *     `rankImpact` (highest blocking fan-out first, tie-broken by
 *     `goalTier` then id — `rankImpact`'s own order, not re-derived here).
 *     UNCHANGED shape/membership rule from before mergeSets existed for
 *     any caller that never opts into `opts.drift` — footprint-conflicted
 *     items were already excluded from `ready` before this cell, shared-
 *     root siblings stay IN `ready` (mergeSets is additive visibility on
 *     top, never a second exclusion).
 *   - `waiting` — ids of `proposed` items with at least one `deps` or
 *     `mergeAfter` target not yet RESOLVED — merge-ready in isolation, but
 *     blocked on merge ORDER. `mergeAfter` (D4/D5) extends this SAME gate
 *     `deps` already used, never a new bucket — it is read ONLY here,
 *     never by `frontier.mjs`'s start-eligibility.
 *   - `conflicts` — the same `{a, b, shared, suggestions}` shape
 *     `footprintOverlapAmong`/`footprintOverlap` already produce, computed
 *     over the dep-clear, sync-clear candidate set. Unchanged shape.
 *   - `mergeSets` — D2's replacement for "silently drop a conflicting pair
 *     from ready": `{items, order, reason}` entries, `reason:
 *     'footprint-overlap' | 'shared-root'` (`'deps-chain'` stays
 *     conceptually inside `waiting` per this cell's own locked
 *     assumption, plan.md). `footprint-overlap` sets are the connected
 *     components of `conflicts` (a chain of overlapping pairs becomes ONE
 *     set, not several) — items here are NOT in `ready` (same exclusion
 *     `conflicts` already caused). `shared-root` sets are 2+ `ready`
 *     candidates resolving to the same root — items here STAY in `ready`
 *     too (informational ordering, not a new exclusion). `order` is
 *     `rankImpact`'s own relative order within the set (D2's permissive
 *     default: auto-serialize in that order; only escalate if a
 *     serialized re-check itself still conflicts — the re-check itself is
 *     Layer 2's job, not this pure function's).
 *   - `blockedOnSync` — ids of otherwise-candidate items whose resolved
 *     root shows `needsSync: true` in the supplied `opts.drift` — always
 *     empty when `opts.drift` is omitted.
 *   - `strandedByResolvedRoot` (tsk-4s0, piece 2 of tsk-4qu's leaf-merge-
 *     into-resolved-root fix) — ids of otherwise-candidate items whose
 *     resolved root (`resolveRoot`) is already RESOLVED
 *     (`isResolvedStatus` — delivered/retrospective/cleanup/done/wontfix).
 *     `approve` now refuses these (`bin/fgos.mjs`'s resolved-root guard),
 *     so they are pulled out of `ready` here too rather than reported as
 *     plainly mergeable — a DIFFERENT hazard from `blockedOnSync` (that
 *     bucket means "the root branch itself needs syncing," not "the root
 *     is closed out and nothing will ever sync it"), kept as its own
 *     bucket rather than folded into `blockedOnSync` so that name's
 *     existing cross-language contract (`packages/herdr-fgos-common/rust/src/fgos.rs`
 *     deserializes it by name) keeps its current meaning unchanged.
 *     Checked independently of `opts.drift` (item status, not a git-shelled
 *     drift computation) — never empty just because `opts.drift` was
 *     omitted, unlike `blockedOnSync`.
 *   - `mergeTier` — `{[id]: 'leaf-to-root' | 'root-to-main'}` for every
 *     `proposed` item, derived from `item.parent` alone (an item with a
 *     parent always merges into SOME `fgw/<root>`, never straight to
 *     `main`) — matches the design report's own §G table split. Named
 *     `mergeTier`, not the canonical reports' bare `tier` (D7): work scale
 *     already exists as a different, unrelated field (`work.size`).
 *   - `supersededOut` — ids of otherwise-`ready` candidates carrying a
 *     `supersededBy` target that is RESOLVED, or itself present in this
 *     same call's ready-set (tsk-2ie D2, docs/history/
 *     tsk-2ie-duplicate-superseded-guard/ — a different D2 than mergeSets'
 *     own above, distinct decision doc). Excluded from `ready`, never
 *     placed in `waiting` (permanently superseded, not "eventually
 *     mergeable once a dep resolves" — a different semantic). Always empty
 *     for every item that never sets `supersededBy` — pure additive
 *     exclusion, same backward-compatible shape `blockedOnSync`/`mergeSets`
 *     already established.
 */
export function mergeReadiness(view, opts = {}) {
  const work = view?.work ?? {};
  const drift = opts.drift ?? {};
  const proposed = Object.values(work).filter((item) => item.status === 'awaiting-approval');

  const waiting = [];
  const candidates = [];
  for (const item of proposed) {
    const deps = Array.isArray(item.deps) ? item.deps : [];
    // work-item-status-delivered-retrospective-cleanup D13: shares
    // frontier.mjs's isResolvedStatus (per decision record 0027) instead of
    // a literal 'done' check — a dep merged (delivered) but not yet fully
    // closed out (retrospective/cleanup) no longer holds up merge-ordering.
    const depsClear = deps.every((dep) => isResolvedStatus(work[dep]));
    const mergeAfter = Array.isArray(item.mergeAfter) ? item.mergeAfter : [];
    const mergeAfterClear = mergeAfter.every((target) => isResolvedStatus(work[target]));
    if (depsClear && mergeAfterClear) {
      candidates.push(item);
    } else {
      waiting.push(item.id);
    }
  }

  const blockedOnSync = [];
  const strandedByResolvedRoot = [];
  const syncClear = [];
  for (const item of candidates) {
    const root = resolveRoot(view, item.id);
    if (drift[root]?.needsSync) {
      blockedOnSync.push(item.id);
    } else if (root !== item.id && isResolvedStatus(work[root])) {
      strandedByResolvedRoot.push(item.id);
    } else {
      syncClear.push(item);
    }
  }

  const conflicts = footprintOverlapAmong(syncClear);
  const conflictedIds = new Set();
  for (const { a, b } of conflicts) {
    conflictedIds.add(a);
    conflictedIds.add(b);
  }

  const rankedIds = rankImpact(view).map((row) => row.id);
  const orderByRank = (ids) => rankedIds.filter((id) => ids.includes(id));

  const readyIdSet = new Set(
    syncClear.map((item) => item.id).filter((id) => !conflictedIds.has(id)),
  );

  // supersededOut (tsk-2ie D2, docs/history/tsk-2ie-duplicate-superseded-
  // guard/): exclude any readyIdSet member whose supersededBy target is
  // RESOLVED (isResolvedStatus, same gate deps/mergeAfter already reuse)
  // OR itself present in this SAME readyIdSet snapshot (about to merge this
  // same round) -- a single pass against the ORIGINAL readyIdSet, checked
  // before any deletion, so a mutual pair (A supersededBy B, B supersededBy
  // A) is excluded on both sides deterministically rather than depending on
  // iteration order. `duplicates` is read by nothing here (D4 --
  // informational only).
  const supersededOutIds = [];
  for (const id of readyIdSet) {
    const target = work[id]?.supersededBy;
    if (typeof target !== 'string') continue;
    if (isResolvedStatus(work[target]) || readyIdSet.has(target)) {
      supersededOutIds.push(id);
    }
  }
  for (const id of supersededOutIds) {
    readyIdSet.delete(id);
  }
  const supersededOut = orderByRank(supersededOutIds);

  const ready = orderByRank([...readyIdSet]);

  const mergeSets = [];

  if (conflictedIds.size > 0) {
    // Connected components over `conflicts`' pairs (a chain of overlapping
    // pairs becomes ONE mergeSet, not several) — a minimal union-find,
    // scoped to this call, never persisted.
    const find = (parents, x) => {
      while (parents.get(x) !== x) x = parents.get(x);
      return x;
    };
    const parents = new Map();
    for (const id of conflictedIds) parents.set(id, id);
    for (const { a, b } of conflicts) {
      const ra = find(parents, a);
      const rb = find(parents, b);
      if (ra !== rb) parents.set(ra, rb);
    }
    const components = new Map();
    for (const id of conflictedIds) {
      const root = find(parents, id);
      if (!components.has(root)) components.set(root, []);
      components.get(root).push(id);
    }
    for (const ids of components.values()) {
      const order = orderByRank(ids);
      mergeSets.push({ items: order, order, reason: 'footprint-overlap' });
    }
  }

  const rootGroups = new Map();
  for (const id of readyIdSet) {
    const root = resolveRoot(view, id);
    if (!rootGroups.has(root)) rootGroups.set(root, []);
    rootGroups.get(root).push(id);
  }
  for (const ids of rootGroups.values()) {
    if (ids.length < 2) continue;
    const order = orderByRank(ids);
    mergeSets.push({ items: order, order, reason: 'shared-root' });
  }

  const mergeTier = {};
  for (const item of proposed) {
    mergeTier[item.id] = item.parent ? 'leaf-to-root' : 'root-to-main';
  }

  // tsk-4zj D6: `ready`/`waiting`/`blockedOnSync`/`supersededOut`/
  // `mergeSets`/`mergeTier` above are all id-referencing, never full item
  // objects (unlike this function's own internal `candidates`/`syncClear`
  // locals, which never reach the return) — so, same as `graphMetrics`'s
  // own `stepByItem` (graph-metrics.mjs), this adds one flat side-map
  // rather than changing any existing id-array shape to an object-array.
  // Covers every id in `work`, not just ids already surfaced in one of the
  // buckets above, so a reader never has to guess which sub-shape an id
  // came from before looking its step up here.
  const stepByItem = Object.fromEntries(
    Object.keys(work).map((id) => [id, effectiveStep(work[id], getDomain(work[id].domain))]),
  );

  return {
    ready,
    waiting,
    conflicts,
    mergeSets,
    // tsk-173: rank-ordered same as ready/mergeSets/supersededOut above --
    // merge next's auto-sync-root branch (bin/fgos.mjs) picks blockedOnSync[0]
    // as "the top-ranked blocked root", a claim only meaningful once this
    // bucket is ordered like every other one already is.
    blockedOnSync: orderByRank(blockedOnSync),
    strandedByResolvedRoot: orderByRank(strandedByResolvedRoot),
    mergeTier,
    supersededOut,
    stepByItem,
  };
}

/**
 * Group `mergeReadiness`'s own buckets into a nested merge tree (tsk-2x9k,
 * docs/history/merge-list-tree-bottleneck-priority/). PURE, same read-only
 * discipline as `mergeReadiness` itself — takes the SAME view plus the
 * `mergeReadiness` result already computed for it, never recomputes
 * `footprintOverlapAmong`/the dep-wait gate internally.
 *
 * D1/D4 (docs/history/merge-list-tree-bottleneck-priority/CONTEXT.md):
 * `mergeReadiness`'s own return shape is NEVER touched by this function —
 * a separate, additive view over the same computed buckets, meant to be
 * composed by a caller (`bin/fgos.mjs`'s `merge list` sub-verb) as
 * `{ ...mergeReadiness(...), tree: mergeTree(...) }`, never spread INTO
 * `mergeReadiness`'s own object. Four existing tests in this module's own
 * test file do an exact `assert.deepEqual` against `mergeReadiness`'s full
 * return shape — adding a field there directly would break them.
 *
 * D2: every id `mergeReadiness` surfaces in ANY bucket (`ready`, `waiting`,
 * `blockedOnSync`, `strandedByResolvedRoot` (tsk-4s0), every id inside a
 * `footprint-overlap` `mergeSets` entry, `supersededOut`) gets a node here
 * — never just `ready`. A `shared-root` `mergeSets` entry is informational
 * only (its items are already in `ready`) and adds no separate status.
 *
 * D3: every nesting level — the top-level root set AND every parent's own
 * children group — is sorted by the SAME order `mergeReadiness` already
 * uses for `ready` (`rankImpact`'s `blocks` descending, tie-broken by
 * `goalTier` then id), never a bespoke per-level sort.
 *
 * D7: a blocked/conflicted node carries a `reason` string naming the
 * specific cause and counterpart item, not just a bare status word.
 *
 * Nesting needs more than the direct candidate ids: a leaf's own immediate
 * parent is very often NOT itself a merge candidate — a decomposed root/
 * intermediate item never merges itself (`cleanup-harness.mjs`'s own
 * "decompose-into-children never itself merges"), so it never appears in
 * any of `mergeReadiness`'s buckets — but it still has to exist as a node
 * for its children to nest under, or the tree cannot show "child merges
 * into parent" at all. This function walks each candidate's `parent`
 * chain and materializes those real ancestors as plain container nodes
 * (`status: 'container'`, no `reason`) — real items, just not themselves
 * proposed for merge right now. An ancestor id not itself present in
 * `view.work` (a dangling/stale `parent` reference) stops the walk there
 * and the child surfaces at the top level instead of being silently
 * dropped — the same "never hide" principle D2 already established.
 */
export function mergeTree(view, readiness, opts = {}) {
  const work = view?.work ?? {};
  const drift = opts.drift ?? {};

  const statusById = new Map();
  for (const id of readiness.waiting) statusById.set(id, { status: 'waiting' });
  for (const id of readiness.blockedOnSync) {
    const root = resolveRoot(view, id);
    const d = drift[root];
    statusById.set(id, {
      status: 'blocked-sync',
      reason: d
        ? `root cần sync: ${d.branch} lệch ${d.aheadOfTarget} ahead / ${d.behindTarget} behind ${d.target}`
        : 'root cần sync',
    });
  }
  for (const set of readiness.mergeSets) {
    if (set.reason !== 'footprint-overlap') continue;
    for (const id of set.items) {
      const conflict = readiness.conflicts.find((c) => c.a === id || c.b === id);
      const counterpart = conflict ? (conflict.a === id ? conflict.b : conflict.a) : null;
      const sharedFiles = conflict?.shared?.length ? conflict.shared.join(', ') : null;
      statusById.set(id, {
        status: 'conflicted',
        reason: counterpart
          ? `conflict với ${counterpart}${sharedFiles ? ` qua ${sharedFiles}` : ''}`
          : 'footprint conflict',
      });
    }
  }
  for (const id of readiness.supersededOut) {
    const target = work[id]?.supersededBy;
    statusById.set(id, {
      status: 'superseded',
      reason: target ? `superseded bởi ${target}` : 'superseded',
    });
  }
  // tsk-4s0 (piece 2 of tsk-4qu's leaf-merge-into-resolved-root fix): a
  // strandedByResolvedRoot id would otherwise get NO node at all here (it
  // is deliberately excluded from `ready` and was never in any other
  // bucket) — violates D2's own "never hide" invariant. Same shape as
  // blockedOnSync just above: a distinct status naming the real cause.
  for (const id of readiness.strandedByResolvedRoot) {
    const root = resolveRoot(view, id);
    const rootItem = work[root];
    statusById.set(id, {
      status: 'stranded-resolved-root',
      reason: rootItem
        ? `root ${root} đã ${rootItem.status} — sẽ không được sync lên main`
        : 'root đã resolved',
    });
  }
  // `ready` last -- mergeReadiness's own membership rule already keeps
  // `ready` disjoint from every exclusion bucket above, so plain
  // assignment here never overwrites a real blocked/conflicted status.
  for (const id of readiness.ready) statusById.set(id, { status: 'ready' });

  const nodeIds = new Set(statusById.keys());
  for (const id of statusById.keys()) {
    let current = work[id];
    const seen = new Set([id]); // cycle guard against a malformed parent loop
    while (current?.parent && work[current.parent] && !seen.has(current.parent)) {
      nodeIds.add(current.parent);
      seen.add(current.parent);
      current = work[current.parent];
    }
  }

  // tsk-4s0: `{ includeDone: true }` (unlike mergeReadiness's own
  // `orderByRank` above, which only ever ranks already-open `candidates`)
  // -- a RESOLVED item can now legitimately need a container node here
  // (an open leaf nesting under its own resolved root is exactly the
  // strandedByResolvedRoot case just above), and `rankImpact`'s default
  // `openIds`-only ranking would silently drop that container id out of
  // `orderByRank`'s filter, hiding every child nested under it -- the
  // same D2 "never hide" invariant this whole function exists to uphold.
  const rankedIds = rankImpact(view, { includeDone: true }).map((row) => row.id);
  const orderByRank = (ids) => rankedIds.filter((id) => ids.includes(id));

  const childrenByParent = new Map();
  const topLevelIds = [];
  for (const id of nodeIds) {
    const parentId = work[id]?.parent;
    if (parentId && work[parentId] && nodeIds.has(parentId)) {
      if (!childrenByParent.has(parentId)) childrenByParent.set(parentId, []);
      childrenByParent.get(parentId).push(id);
    } else {
      topLevelIds.push(id);
    }
  }

  const buildNode = (id) => {
    const info = statusById.get(id) ?? { status: 'container' };
    const kids = childrenByParent.get(id) ?? [];
    return {
      id,
      title: work[id]?.title ?? id,
      ...info,
      children: orderByRank(kids).map(buildNode),
    };
  };

  return orderByRank(topLevelIds).map(buildNode);
}

/**
 * The still-open items that merge into the SAME target ref as `landedId` —
 * the only branches a land can possibly have put behind. An item's target is
 * `fgw/<parent>` when it has a parent and the trunk otherwise, so "same
 * target" is exactly "same parent", with two parentless items both aimed at
 * the trunk.
 *
 * Two exclusions, both because the excluded item has nothing to compare:
 * a RESOLVED item (`isResolvedStatus`) has already merged or been dropped,
 * and a pre-claim (`todo`) item's `fgw/<id>` branch is created back at
 * decompose carrying no commit of its own — its changed-file set is empty,
 * so running a diff for it buys a guaranteed-empty answer. Refreshing that
 * decompose→pick gap is `pick`-time refresh's job, not this detection's.
 */
export function openLeavesSharingTarget(view, landedId) {
  const work = view?.work ?? {};
  const landed = work[landedId];
  if (!landed) return [];
  const target = landed.parent ?? null;
  return Object.values(work)
    .filter((item) => item.id !== landedId
      && (item.parent ?? null) === target
      && item.status !== 'todo'
      && !isResolvedStatus(item))
    .map((item) => item.id)
    .sort();
}

/**
 * D4's three-way split over REAL changed-file sets — never declared
 * `footprint`, which an item fills in by hand and can leave stale or empty
 * (`footprintOverlapAmong` above compares exactly that weaker signal; here
 * git has already given the ground truth, so nothing needs to stand in for
 * it).
 *
 * A leaf sharing no path with what just landed produces NOTHING — no
 * notification, no mark. That silence is the point: a root landing 13
 * children sequentially would otherwise pay ~78 catchup+verify rounds, and
 * most of them discover nothing collided. A leaf that does share a path
 * either goes to the session that owns it — cheapest to fix while that
 * context is still in someone's head, and the owner is the only party
 * allowed to touch that branch — or, with no session behind it, is marked
 * stale for the lazy catchup it will get when it reaches the merge queue.
 *
 * `leaves` entries are `{id, files, sessionIds}`; the caller supplies the
 * real diffs and the real session registry, keeping this half pure.
 */
export function classifyPostLandDrift({ landedFiles = [], leaves = [] } = {}) {
  const landed = new Set(landedFiles);
  const notify = [];
  const stale = [];
  for (const leaf of leaves) {
    const shared = (leaf.files ?? []).filter((file) => landed.has(file)).sort();
    if (shared.length === 0) continue;
    const sessionIds = leaf.sessionIds ?? [];
    if (sessionIds.length > 0) {
      notify.push({ id: leaf.id, shared, sessionIds });
    } else {
      stale.push({ id: leaf.id, shared });
    }
  }
  return { notify, stale };
}

// priority-formula.mjs — pure calculation for work-item-priority-matrix
// (tsk-4y5, D6). No fs/Date.now/mutation — same discipline as
// src/state/impact.mjs and src/state/graph-metrics.mjs.
//
// priority = invert((impact * weight(urgent)) / max(effort, floor) * discount(risk))
//
// `invert()` matters: work.priority's schema/sort contract is ASC with
// absent-last (Data Dictionary #25) — smaller number = higher priority —
// while impact/urgent/effort/risk combine into a raw score where BIGGER
// means MORE important. Getting this backwards silently reorders every
// item's priority; see CONTEXT.md D6 for why this is called out as the
// single highest-consequence correctness risk in this feature.

export const URGENCY_WEIGHTS = Object.freeze({ low: 0.5, medium: 1, high: 2, critical: 4 });
export const RISK_DISCOUNTS = Object.freeze({ light: 1, standard: 0.85, heavy: 0.6 });
export const EFFORT_FLOOR = 1;
export const PRIORITY_SCALE = 10000;

// D5: reuses fgos-coding-planning's own mode vocabulary (SKILL.md step 2's mode
// gate: tiny/small/standard/high-risk/spike) rather than a bespoke numeric
// estimator with no precedent in the repo. `spike` gets a low number
// deliberately: a spike's own effort (answering one yes/no question) is
// typically small even though its OUTCOME is high-stakes for what comes
// after -- that stakes signal belongs to `risk`/`impact`, not `effort`.
export const MODE_EFFORT = Object.freeze({ tiny: 1, small: 2, standard: 4, 'high-risk': 8, spike: 2 });

export function effortForMode(mode) {
  return MODE_EFFORT[mode] ?? MODE_EFFORT.standard;
}

export function weightForUrgency(urgent) {
  return URGENCY_WEIGHTS[urgent] ?? URGENCY_WEIGHTS.medium;
}

export function discountForRisk(risk) {
  return RISK_DISCOUNTS[risk] ?? RISK_DISCOUNTS.standard;
}

// tsk-4hb: `risk` is free text (Data Dictionary #6, docs/specs/work-state.md),
// so a value outside RISK_DISCOUNTS is spec-legal, not a data error --
// discountForRisk's own `?? standard` fallback cannot tell "absent" (a
// legitimate default) apart from "present but unrecognized" (silently
// masked, same discount either way). This pure query lets a caller that
// already does side effects (addDecision) log the distinction instead of
// leaving it invisible.
export function isRecognizedRisk(risk) {
  return Object.hasOwn(RISK_DISCOUNTS, risk);
}

// D8: de-risking value feeds `impact` as a bonus (never `risk`) — sub-linear
// (sqrt) so a very large blast radius still yields a bounded bonus rather
// than dominating the whole score. 0 when no measurement exists yet (the
// clarify rough pass, before a code target is known).
export function derisknBonus(blastRadius) {
  if (!Number.isFinite(blastRadius) || blastRadius <= 0) return 0;
  return Math.sqrt(blastRadius);
}

// D4/D8: the SAME blast-radius measurement also discounts `risk` further —
// never boosts, only ever shrinks the multiplier further below the
// keyword-based baseline. Reading the same number twice for two different
// roles is not circular (see CONTEXT.md D8): neither role depends on the
// other's *output*, both read the same upstream measurement independently.
export function discountForRiskWithBlastRadius(risk, blastRadius) {
  const base = discountForRisk(risk);
  if (!Number.isFinite(blastRadius) || blastRadius <= 0) return base;
  return base / (1 + Math.sqrt(blastRadius) / 10);
}

// D3: impact = blocks (STR21 rankImpact, always available) + semantic
// relatedness (judge-estimated, always available) + de-risk bonus (only
// once a real blast-radius measurement exists — 0 at the clarify rough
// pass, per D8).
export function computeImpact({ blocks = 0, semanticRelatedness = 0, blastRadius } = {}) {
  return blocks + semanticRelatedness + derisknBonus(blastRadius);
}

/**
 * D6's calculated `priority`. `effort`/`blastRadius` are optional (absent
 * at the clarify rough pass, per plan.md's phased design) — `effort`
 * defaults to `EFFORT_FLOOR` (assume the cheapest case until decompose
 * knows better, never divide-by-zero), `blastRadius` defaults to no bonus
 * / no extra discount (handled inside `derisknBonus`/
 * `discountForRiskWithBlastRadius`).
 */
export function computePriority({ impact = 0, urgent, effort = EFFORT_FLOOR, risk, blastRadius } = {}) {
  const w = weightForUrgency(urgent);
  const e = Math.max(effort, EFFORT_FLOOR);
  const d = discountForRiskWithBlastRadius(risk, blastRadius);
  const raw = (impact * w * d) / e;
  return Math.round(PRIORITY_SCALE / (raw + 1));
}

